/**
 * Which LLM reads the request text. It only ever sees the text, the locale and the
 * names of saved places; map data never reaches it.
 *
 * `base_url` sends the LLM calls to your own server or proxy instead of the
 * provider (for example, to keep the provider key off end users' devices). It
 * must speak the provider's OpenAI-compatible API.
 */

public enum LlmBackend: Equatable, Hashable {
    
    /**
     * Anthropic's Claude. `model` defaults to [`DEFAULT_ANTHROPIC_MODEL`].
     */
    case anthropic(model: String?, baseUrl: String?
    )
    case openAi(model: String, baseUrl: String?
    )
    /**
     * Google Gemini through its OpenAI-compatible endpoint.
     */
    case gemini(model: String, baseUrl: String?
    )
    /**
     * Any OpenAI-compatible server, for example a local `mlx_lm.server`, vLLM or
     * llama.cpp server. Set `fine_tuned` when it serves Waylingo's fine-tuned
     * parser model (it then gets the short prompt it was trained with).
     */
    case openAiCompatible(baseUrl: String, model: String, fineTuned: Bool
    )





}

#if compiler(>=6)
extension LlmBackend: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLlmBackend: FfiConverterRustBuffer {
    typealias SwiftType = LlmBackend

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LlmBackend {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .anthropic(model: try FfiConverterOptionString.read(from: &buf), baseUrl: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 2: return .openAi(model: try FfiConverterString.read(from: &buf), baseUrl: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 3: return .gemini(model: try FfiConverterString.read(from: &buf), baseUrl: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 4: return .openAiCompatible(baseUrl: try FfiConverterString.read(from: &buf), model: try FfiConverterString.read(from: &buf), fineTuned: try FfiConverterBool.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LlmBackend, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .anthropic(model,baseUrl):
            writeInt(&buf, Int32(1))
            FfiConverterOptionString.write(model, into: &buf)
            FfiConverterOptionString.write(baseUrl, into: &buf)
            
        
        case let .openAi(model,baseUrl):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(model, into: &buf)
            FfiConverterOptionString.write(baseUrl, into: &buf)
            
        
        case let .gemini(model,baseUrl):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(model, into: &buf)
            FfiConverterOptionString.write(baseUrl, into: &buf)
            
        
        case let .openAiCompatible(baseUrl,model,fineTuned):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(baseUrl, into: &buf)
            FfiConverterString.write(model, into: &buf)
            FfiConverterBool.write(fineTuned, into: &buf)
            
        }
    }
}


