/**
 * Each variant carries a `detail` (not `message`, which would clash with the
 * built-in `message` of Kotlin and Java exceptions).
 */
public 
enum WaylingoError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The configuration is unusable (for example, a missing model name).
     */
    case InvalidConfig(detail: String
    )
    /**
     * The request is unusable (empty or too long, settings out of range).
     */
    case InvalidRequest(detail: String
    )
    /**
     * The previous result cannot be continued (not a Waylingo result, another
     * version or provider, not signed by this engine, no plan).
     */
    case IncompatibleResult(detail: String
    )
    /**
     * A choice names a stop, place or candidate that the result did not offer.
     */
    case UnknownChoice(detail: String
    )
    /**
     * The query did not finish within the configured time.
     */
    case Timeout(detail: String
    )
    /**
     * A bug or an unexpected failure inside Waylingo.
     */
    case Internal(detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension WaylingoError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeWaylingoError: FfiConverterRustBuffer {
    typealias SwiftType = WaylingoError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WaylingoError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidConfig(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidRequest(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 3: return .IncompatibleResult(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 4: return .UnknownChoice(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Timeout(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Internal(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: WaylingoError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidConfig(detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .InvalidRequest(detail):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .IncompatibleResult(detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .UnknownChoice(detail):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Timeout(detail):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Internal(detail):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


